use std::{fs,path::Path};
use serde_json::{Value,json};
use sf_simulation::{Engine,EngineInput};
fn read(path:&Path)->Value{serde_json::from_slice(&fs::read(path).unwrap()).unwrap()}
fn make(v:&Value)->Engine{Engine::new(EngineInput{run_id:serde_json::from_value(json!("P302-LINE-GRADE")).unwrap(),input_ref:serde_json::from_value(v["input_ref"].clone()).unwrap(),project:serde_json::from_value(v["project"].clone()).unwrap(),scenario:serde_json::from_value(v["scenario"].clone()).unwrap(),definitions:serde_json::from_value(v["definitions"].clone()).unwrap(),scope:serde_json::from_value(v["scenario"]["scope"].clone()).unwrap()}).unwrap()}
fn run(v:&Value)->Value{let mut e=make(v);while !e.is_finished(){e.step();}serde_json::to_value(e.snapshot()).unwrap()}
fn main(){let root=std::env::current_dir().unwrap();let out=root.join("scenarios/媒体表现/runtime-line-grade");let base=root.join("modules/media/p302-line-grade");let inventory=read(&base.join("inventory.json"));let expected=read(&root.join("tests/planner/media/expected.json"));let mut packages=vec![];let mut checked=vec![];
    for entry in fs::read_dir(base.join("installable")).unwrap(){let dir=entry.unwrap().path();if !dir.is_dir(){continue;}let document=read(&dir.join("module.json"));let _:sf_domain::Versioned<sf_domain::ModulePackage>=serde_json::from_value(document.clone()).unwrap();let p=document["data"].clone();for f in p["files"].as_array().unwrap(){assert!(dir.join(f["path"].as_str().unwrap()).is_file());}for a in p["assets"].as_array().unwrap(){assert!(p["rights"].as_array().unwrap().iter().any(|r|r["asset_ref"]==a["id"]&&r["license"]=="CC0-1.0"&&r["redistribution_confirmed"]==true));}checked.push(p["definition"]["id"].clone());if !p["definition"]["id"].as_str().unwrap().ends_with(".fit")&&!p["definition"]["id"].as_str().unwrap().contains("control-box")&&!p["definition"]["id"].as_str().unwrap().contains("carton"){packages.push(p);}}
    assert_eq!(packages.len(),24);assert_eq!(checked.len(),32);let mut comparisons=vec![];
    // Reuse the seven already-frozen business fixtures and original expectations unchanged.
    // These are CNC visual-substitution regressions, not a new L03 or Native acceptance count.
    for case in ["calendar","busy","output","interrupt","missing","cycle","zero"]{
        let input=read(&root.join(format!("scenarios/媒体表现/runtime/{case}.input.json")));let baseline=run(&input);fs::write(out.join(format!("{case}.baseline.run.json")),serde_json::to_vec_pretty(&baseline).unwrap()).unwrap();
        for package in &packages{let mut candidate=input.clone();for definition in candidate["definitions"].as_array_mut().unwrap(){if definition["payload"]["category"]=="devices"{definition["payload"]["data"]["presentation"]=package["definition"]["payload"]["data"].clone();}}let result=run(&candidate);for field in expected["identical_fields"].as_array().unwrap(){let name=field.as_str().unwrap();assert_eq!(baseline[name],result[name],"{case}/{}/{name}",package["definition"]["id"]);}let job=result["jobs"].as_array().unwrap().iter().find(|j|j["operation_ref"]["id"]=="w5.op.phased").unwrap();assert_eq!(job["state"],expected["cases"][case]["state"]);assert_eq!(job["finished_at_ms"],expected["cases"][case]["finished_at_ms"]);comparisons.push(json!({"case":case,"media":package["definition"]["id"],"identical_fields":expected["identical_fields"],"state":job["state"],"finished_at_ms":job["finished_at_ms"],"passed":true}));}
    }
    let report=json!({"passed":true,"source":"sf_simulation::Engine / pinned matching prebuilt rlibs from runtime/actual-libraries.json","canonical_module_count":checked.len(),"checked_modules":checked,"asset_matrix_runs":comparisons.len(),"reused_business_cases":7,"new_business_case_coverage":0,"original_counts_unchanged":true,"comparison":comparisons,"instances":inventory["instances"],"resources":inventory["resources"],"host_native_or_live_old_run_draft_isolation_acceptance":false});fs::write(out.join("engine-comparison.json"),serde_json::to_vec_pretty(&report).unwrap()).unwrap();println!("32 canonical ModulePackages accepted by sf_domain; 168 actual Engine visual-substitution runs equal on 9 frozen fields. Reused 7 business cases; no new semantic coverage or Native/Host claim.");}

